const test=require('node:test');const assert=require('node:assert/strict');const vm=require('node:vm');const fs=require('node:fs');
function healthSample(a,steps=100,syncedAt=Date.now()){a.context.healthSampleSteps=steps;a.context.healthSampleTime=syncedAt;a.run("window.nextstepHealthResult({status:'ready',days:Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));return {date:localDate(d),steps:healthSampleSteps,sources:['daily.source']}}),sources:['batch.source'],syncedAt:healthSampleTime})")}
test('app updates entry opens only the native updater and retains existing data',()=>{const a=app();assert.equal(a.run('appUpdateSettings()'),'');let opened=0;a.context.window.NextStepAndroid={openAppUpdates(){opened++}};a.run('openSettings()');assert.match(a.element('workout-content').innerHTML,/检查更新 \/ 自动更新/);a.listeners.get('click')[0]({target:{closest(){return {dataset:{action:'app-updates'}}}}});assert.equal(opened,1);assert.equal(a.run('records.length'),0);assert.equal(a.run('activityRecords.length'),0);assert.equal(a.run('draft'),null)});
test('browser export action serializes persisted daily activity',()=>{const a=app();healthSample(a,123,1000);let payload,clicked=false;a.context.Blob=class{constructor(parts){payload=JSON.parse(parts[0])}};a.context.URL={createObjectURL(){return 'blob:test'},revokeObjectURL(){}};a.context.document.createElement=()=>({click(){clicked=true}});a.listeners.get('click')[0]({target:{closest(){return {dataset:{action:'export'}}}}});assert.equal(clicked,true);assert.equal(payload.version,2);assert.equal(payload.activityRecords.length,7);assert.equal(payload.activityRecords[0].steps,123);assert.equal(payload.records.length,0)});
test('Android export adapter sends the same activity structure to its native bridge',()=>{const path=require('node:path');const dir=fs.mkdtempSync(path.join(__dirname,'export-check-'));try{require('node:child_process').execFileSync(process.execPath,[path.join(__dirname,'../../android-app/prepare-assets.cjs'),dir]);const source=fs.readFileSync(path.join(dir,'www/app.js'),'utf8'),a=app({},source);healthSample(a,456,2000);let payload;a.context.window.NextStepAndroid={exportRecords(json){payload=JSON.parse(json)}};a.listeners.get('click')[0]({target:{closest(){return {dataset:{action:'export'}}}}});assert.equal(payload.version,2);assert.equal(payload.activityRecords.length,7);assert.equal(payload.activityRecords[0].steps,456);assert.deepEqual(payload.records,[])}finally{for(const name of ['index.html','styles.css','home.css','app.js'])fs.unlinkSync(path.join(dir,'www',name));fs.rmdirSync(path.join(dir,'www'));fs.rmdirSync(dir)}});
test('daily steps upsert across refreshes, survive restart and export with existing records',()=>{const a=app();a.run("records=[{id:1,date:localDate(),mode:'sport',minutes:10,sets:0,volume:0}]");healthSample(a,100,1000);healthSample(a,200,2000);assert.equal(a.run('activityRecords.length'),7);assert.equal(a.run('activityRecords[0].steps'),200);assert.equal(a.run("activityRecords[0].sources[0]"),'daily.source');assert.equal(a.run('summary(rangeRecords()).count'),1);assert.equal(a.run('summary(rangeRecords()).minutes'),10);assert.equal(a.run('exportData().version'),2);assert.equal(a.run('exportData().records.length'),1);assert.equal(a.run('exportData().activityRecords.length'),7);const resumed=app({'nextstep.activityRecords':JSON.parse(a.storage.get('nextstep.activityRecords'))});assert.equal(resumed.run('activityRecords.length'),7);assert.match(resumed.run('healthCard()'),/200<small>今日步数/);assert.match(resumed.run('training()'),/查看每日记录（7 天）/);healthSample(a,50,3000);assert.equal(a.run('activityRecords[0].steps'),50);healthSample(a,999,2000);assert.equal(a.run('activityRecords[0].steps'),50)});
test('missing, denied and failed reads retain saved activity including dates outside the read window',()=>{const a=app({'nextstep.activityRecords':[{kind:'steps',provider:'health-connect',date:'2000-01-01',steps:500,sources:['old.source'],syncedAt:1}]});healthSample(a,0,1000);assert.equal(a.run('activityRecords.length'),8);assert.equal(a.run('activityRecords[0].steps'),0);healthSample(a,null,2000);assert.equal(a.run('activityRecords.length'),8);assert.equal(a.run('activityRecords[0].syncedAt'),1000);a.run("window.nextstepHealthResult({status:'permission',message:'未授权'})");assert.equal(a.run('activityRecords.length'),8);assert.equal(a.run('pendingActivityRecords'),null);assert.match(a.run('stepHistory()'),/2000-01-01/);assert.equal(a.run('records.length'),0)});
test('failed step persistence retains retry state without claiming the new count was saved',()=>{const a=app();healthSample(a,100,1000);a.context.localStorage.setItem=()=>{throw Error('quota')};healthSample(a,200,2000);assert.equal(a.run('activityRecords[0].steps'),100);assert.equal(a.run('pendingActivityRecords[0].steps'),200);assert.equal(a.run('exportData().activityRecords[0].steps'),100);assert.match(a.run('healthCard()'),/重试保存步数/);assert.equal(JSON.parse(a.storage.get('nextstep.activityRecords'))[0].steps,100);a.run("window.nextstepHealthResult({status:'error',message:'无法连接'})");a.context.localStorage.setItem=(k,v)=>a.storage.set(k,v);a.run('retryStepSave()');assert.equal(a.run('activityRecords[0].steps'),200);assert.equal(a.run('pendingActivityRecords'),null);assert.equal(JSON.parse(a.storage.get('nextstep.activityRecords'))[0].steps,200)});
test('invalid health dates, duplicate dates and malformed sources never overwrite saved steps',()=>{const a=app();healthSample(a,100,1000);for(const mutation of ["days[0].date='2026-02-30'","days[0].date=days[1].date","days[0].steps=-1","days[0].sources=[null]","days[0]=null"]){a.run("{const days=savedStepDays();"+mutation+";window.nextstepHealthResult({status:'ready',days,sources:[],syncedAt:2000})}");assert.equal(a.run('healthSteps.status'),'error');assert.equal(a.run('activityRecords[0].steps'),100);assert.equal(a.run('activityRecords.length'),7)}});
test('health steps keep missing data distinct from zero and never change training totals',()=>{const a=app();a.run("window.NextStepAndroid={readHealthSteps(){}};window.nextstepHealthResult({status:'ready',days:Array.from({length:7},(_,i)=>({date:localDate(new Date(Date.now()-(6-i)*86400000)),steps:i===6?0:null})),sources:['source.<test>'],syncedAt:Date.now()})");assert.doesNotMatch(a.run('today()'),/id="health-card"/);assert.match(a.run('training()'),/id="health-card"/);assert.match(a.run('healthCard()'),/0<small>今日步数/);assert.match(a.run('healthCard()'),/source.&lt;test&gt;/);assert.match(a.run('healthCard()'),/暂无数据，不代表/);assert.equal(a.run('summary(rangeRecords()).count'),0);assert.equal(a.storage.has('nextstep.health'),false);a.run("window.nextstepHealthResult({status:'permission',message:'步数权限已撤销'})");assert.match(a.run('healthCard()'),/source.&lt;test&gt;/);assert.match(a.run('healthCard()'),/步数权限已撤销/)});
test('health rejects invalid counts and allows retry after bridge failure',()=>{const a=app();a.run("window.NextStepAndroid={readHealthSteps(){throw Error('bridge')}};refreshHealthSteps(true)");assert.equal(a.run('healthPending'),false);assert.equal(a.run('healthSteps.status'),'error');a.run("window.nextstepHealthResult({status:'ready',days:[{date:localDate(),steps:-1}],sources:[],syncedAt:Date.now()})");assert.equal(a.run('healthSteps.status'),'error');assert.match(a.run('healthCard()'),/格式无效/);assert.equal(a.run('records.length'),0)});
test('historical strength edits recalculate and persist totals',()=>{const a=app();a.run("records=[{id:1,date:localDate(),name:'训练',minutes:10,sets:1,volume:100,exercises:1,items:[{name:'哑铃划船',type:'weighted',sets:[{done:true,weight:10,reps:10}]}]}]");assert.match(a.run('training()'),/data-edit-record/);assert.equal(a.run("pages.find(p=>p[0]==='training')[1]"),'记录');assert.equal(a.run("updateRecord('1',{name:'修改后',date:localDate(),minutes:'20','weight-0-0':'20','reps-0-0':'12'})"),true);assert.equal(a.run('summary(rangeRecords()).volume'),240);assert.equal(JSON.parse(a.storage.get('nextstep.records'))[0].minutes,20)});
test('sport edits and deletion update totals while failed storage preserves records',()=>{const a=app();a.run("saveSport({sport:'walk',minutes:'30',weight:'70',date:localDate()})");assert.equal(a.run("updateRecord(records[0].id,{name:'快走',date:localDate(),minutes:'60',sport:'walk-brisk',weight:'80'})"),true);assert.equal(a.run('records[0].calories'),384);a.run('recordDeleteDialog(String(records[0].id))');assert.match(a.element('workout-content').innerHTML,/确认删除/);a.context.localStorage.setItem=()=>{throw Error('quota')};assert.equal(a.run('deleteRecord(records[0].id)'),false);assert.equal(a.run('records.length'),1);a.context.localStorage.setItem=(k,v)=>a.storage.set(k,v);assert.equal(a.run('deleteRecord(records[0].id)'),true);assert.equal(a.run('summary(rangeRecords()).minutes'),0)});
function app(initial={},source){const listeners=new Map();const elements=new Map();const element=id=>{if(!elements.has(id))elements.set(id,{textContent:'',innerHTML:'',classList:{add(){},remove(){}},addEventListener(){},showModal(){this.open=true},close(){this.open=false}});return elements.get(id)};const storage=new Map(Object.entries(initial).map(([k,v])=>[k,JSON.stringify(v)]));const context=vm.createContext({Date,console,setInterval(){},setTimeout(){},clearTimeout(){},location:{hash:''},localStorage:{getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v),removeItem:k=>storage.delete(k)},document:{querySelector:()=>({style:{}}),getElementById:element,addEventListener(type,fn){if(!listeners.has(type))listeners.set(type,[]);listeners.get(type).push(fn)}},window:{addEventListener(){}}});vm.runInContext(source||fs.readFileSync(require('node:path').join(__dirname,'../dist/app.js'),'utf8'),context);return {run:code=>vm.runInContext(code,context),context,storage,element,listeners}}
test('empty journal uses actual zero values and a single navigation entry',()=>{const a=app();assert.equal(a.run('summary(rangeRecords()).count'),0);assert.equal(a.run("pages.some(p=>p[0]==='trends')"),false);assert.match(a.run('training()'),/还没有训练记录/);assert.doesNotMatch(a.run('training()'),/示例报表|310 kcal/)});
test('summary includes only saved records in current range',()=>{const a=app();a.run("records=[{id:1,date:localDate(),name:'训练',minutes:12,sets:2,volume:800,exercises:1,items:[]},{id:2,date:'2000-01-01',minutes:99,sets:9,volume:999}]");assert.equal(a.run('summary(rangeRecords()).minutes'),12);assert.equal(a.run('summary(rangeRecords()).volume'),800);assert.match(a.run('training()'),/查看详情/);a.run("render('trends')");assert.equal(a.run('currentPage'),'training')});
test('finished workout updates records and trend totals',()=>{const a=app();a.run("saveProfile({...profileDefaults,goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中',name:'测试',height:'175',weight:'70'});startWorkout();draft.items[0].type='weighted';draft.items[0].sets[0].weight=40;draft.items[0].sets[0].done=true;finishWorkout()");assert.equal(a.run('records.length'),1);assert.equal(a.run('draft'),null);assert.equal(a.run('summary(rangeRecords()).volume'),400);assert.ok(a.storage.has('nextstep.records'))});
test('storage failure retains the complete draft',()=>{const a=app();a.run("saveProfile({...profileDefaults,goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中',name:'测试',height:'175',weight:'70'});startWorkout();draft.items[0].sets[0].done=true");a.context.localStorage.setItem=()=>{throw Error('quota')};a.run('finishWorkout()');assert.equal(a.run('records.length'),0);assert.equal(a.run('draft.items[0].sets[0].done'),true)});

test('first use prompts setup and settings leave main navigation',()=>{const a=app();assert.equal(a.run('reminderReason'),'first');assert.equal(a.run('pages.length'),2);assert.equal(a.element('workout-dialog').open,true);assert.match(a.run('plan()'),/完善资料并生成计划/)});
test('generation respects equipment, frequency, available time and workload',()=>{const a=app();for(const count of [2,3,4,5]){a.run("saveProfile({...profileDefaults,goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中',name:'用户',height:'175',weight:'70',frequency:'每周 "+count+" 次',equipment:'哑铃',duration:'20'})");assert.equal(a.run('profile.trainingPlan.days.filter(d=>d.items.length).length'),count);assert.equal(a.run('nextSession().items.length'),3);assert.match(a.run('nextSession().items[0].name'),/哑铃/);assert.equal(a.run('nextSession().items[0].sets'),2)}});
test('profile and plan save together without discarding an active workout',()=>{const a=app();a.run("saveProfile({...profileDefaults,goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中',name:'用户',height:'175',weight:'70'});startWorkout();originalDraftName=draft.items[0].name;draft.items[0].sets[0].done=true;saveProfile({...profileDefaults,goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中',name:'用户',height:'175',weight:'71',equipment:'健身房'})");assert.equal(a.run('draft.items[0].sets[0].done'),true);assert.equal(a.run('draft.items[0].name'),a.run('originalDraftName'));assert.equal(a.run("nextSession().items.every(e=>e.type==='weighted'&&e.weight>0)"),true);assert.equal(a.run('reminderReason'),'')});
test('invalid or failed profile save does not replace existing plan',()=>{const a=app();assert.equal(a.run("saveProfile({...profileDefaults,goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中',name:'用户',height:'0',weight:'70'})"),false);a.run("saveProfile({...profileDefaults,goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中',name:'用户',height:'175',weight:'70'})");a.context.localStorage.setItem=()=>{throw Error('quota')};assert.equal(a.run("saveProfile({...profileDefaults,goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中',name:'用户',height:'175',weight:'80'})"),false);assert.equal(a.run('profile.weight'),70)});

test('return reminder depends on inactivity rather than profile age',()=>{const profile={name:'用户',height:175,weight:70,updatedAt:Date.now()-90*86400000};assert.equal(app({'nextstep.profile':profile,'nextstep.lastActive':Date.now()-31*86400000}).run('reminderReason'),'return');assert.equal(app({'nextstep.profile':profile,'nextstep.lastActive':Date.now()-86400000}).run('reminderReason'),'')});

test('fresh install has no preset personal data, records or training plan',()=>{const a=app();assert.equal(a.run('records.length'),0);assert.equal(a.run('draft'),null);assert.equal(a.run('profile.trainingPlan'),undefined);assert.equal(a.run("Object.values(profileDefaults).every(v=>v==='')"),true);assert.match(a.element('workout-content').innerHTML,/请选择/)});

test('monthly buckets contain all saved minutes once and stop at month end',()=>{const a=app();a.run("period='month';records=[{date:localDate(rangeStart()),minutes:7,sets:1,volume:0},{date:localDate(),minutes:11,sets:1,volume:0},{date:'2000-01-01',minutes:1000}]");assert.equal(a.run('chartBuckets().reduce((n,b)=>n+b.minutes,0)'),18);assert.equal(a.run('chartBuckets().length'),a.run('Math.ceil(new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate()/7)'));assert.equal(a.run('chartBuckets().at(-1).to'),a.run('localDate(new Date(new Date().getFullYear(),new Date().getMonth()+1,0))'));assert.match(a.run('bars()'),/training-calendar/)});
test('range switch updates statistics without recreating the page or navigation',()=>{const a=app();a.run("render('training')");const original=a.element('app').innerHTML;let focused=false;const card={innerHTML:'',querySelector:()=>({focus:options=>{focused=options.preventScroll}})},metrics={innerHTML:''},rows={innerHTML:''};a.context.document.querySelector=selector=>({'.activity-card':card,'.journal-metrics':metrics,'.journal-period-records':rows}[selector]);a.run("changePeriod('month')");assert.equal(a.element('app').innerHTML,original);assert.match(card.innerHTML,/aria-pressed="true"/);assert.match(rows.innerHTML,/本月训练记录/);assert.ok(metrics.innerHTML);assert.ok(focused);a.run("changePeriod('week')");assert.match(rows.innerHTML,/本周训练记录/)});

test('month calendar has one cell per day and sums daily sessions without example data',()=>{const a=app();a.run("period='month';records=[{date:localDate(),minutes:10,sets:1,volume:0},{date:localDate(),minutes:25,sets:1,volume:0}]");assert.equal(a.run('monthDays().find(d=>d.date===localDate()).count'),2);assert.equal(a.run('monthDays().find(d=>d.date===localDate()).level'),2);assert.equal(a.run('monthDays().reduce((n,d)=>n+d.minutes,0)'),35);assert.equal(a.run("(monthlyCalendar().match(/data-calendar-date=/g)||[]).length"),a.run('monthDays().length'));assert.match(a.run('calendarDetail(localDate())'),/2 次训练 · 35 分钟/)});

test('home prioritizes training before statistics when there is no workout today',()=>{const a=app();a.run("saveProfile({...profileDefaults,name:'用户',height:'175',weight:'70',goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中'});profile.trainingPlan.days[(new Date().getDay()+6)%7]={name:'今日测试计划',items:nextSession().items}");const html=a.run('today()');assert.ok(html.indexOf('home-workout')<html.indexOf('home-week-plan'));assert.match(html,/今日训练内容/);a.run("records=[{date:localDate(),minutes:5,sets:1,volume:0}]");const done=a.run('today()');assert.ok(done.indexOf('home-workout')<done.indexOf('home-week-plan'));assert.match(done,/今日训练已记录/)});
test('training mode selection does not start a timer and free training needs no plan',()=>{const a=app();a.run('workoutModeDialog()');assert.equal(a.run('draft'),null);assert.match(a.element('workout-content').innerHTML,/自由训练/);assert.equal(a.run("startFreeWorkout({exercise:'自选划船',sets:'2',reps:'12',weight:'5'})"),true);assert.equal(a.run('draft.mode'),'free');assert.equal(a.run('draft.items[0].sets.length'),2);assert.ok(a.run('draft.startedAt')>0);a.run("startFreeWorkout({exercise:'自选深蹲',sets:'3',reps:'10',type:'bodyweight',weight:''})");assert.equal(a.run('draft.items.length'),2);a.run('completeSet(0);finishWorkout()');assert.equal(a.run('records[0].mode'),'free');assert.equal(a.run('records[0].name'),'自由训练');assert.equal(a.run('records[0].volume'),0)});
test('rest countdown persists across reload and duplicate completion is ignored',()=>{const a=app();a.run("startFreeWorkout({exercise:'俯卧撑',sets:'2',reps:'10',type:'bodyweight',weight:''});changeWorkoutRest(120);completeSet(0)");assert.ok(a.run('draft.restEnd-Date.now()')>118000);assert.ok(a.run('draft.items[0].sets[0].completedAt')>0);const initial=Object.fromEntries([...a.storage.entries()].map(([k,v])=>[k,JSON.parse(v)]));const resumed=app(initial);assert.equal(resumed.run('restEnd'),a.run('draft.restEnd'));resumed.run('completeSet(0)');assert.equal(resumed.run('restEnd'),a.run('draft.restEnd'));assert.equal(resumed.run('draft.items[0].sets[0].done'),true);resumed.run('endRest()');assert.equal(resumed.run('restEnd'),0)});
test('workout elapsed time is measured from explicit start',()=>{const a=app();a.run("startFreeWorkout({exercise:'划船',sets:'1',reps:'10',weight:'5'});draft.startedAt=Date.now()-125000");assert.match(a.run('elapsedText()'),/^00:02:05$/);a.run('completeSet(0);finishWorkout()');assert.equal(a.run('records[0].minutes'),2);assert.ok(a.run('records[0].seconds')>=125);assert.ok(a.run('records[0].endedAt-records[0].startedAt')>=125000)});

test('single set flow displays only one set and transitions through rest to next group',()=>{const a=app();a.run("startFreeWorkout({exercise:'深蹲',sets:'3',reps:'10',type:'bodyweight',weight:''})");assert.match(a.element('workout-content').innerHTML,/1\/3 组/);assert.doesNotMatch(a.element('workout-content').innerHTML,/<table/);assert.equal((a.element('workout-content').innerHTML.match(/data-field="reps"/g)||[]).length,1);a.run('completeSet(0)');assert.match(a.element('workout-content').innerHTML,/休息一下，再继续/);assert.doesNotMatch(a.element('workout-content').innerHTML,/current-weight/);a.run('endRest()');assert.match(a.element('workout-content').innerHTML,/2\/3 组/);a.run('completeSet(1);endRest();completeSet(2)');assert.match(a.element('workout-content').innerHTML,/这次训练感觉怎么样/);assert.equal(a.run('restEnd'),0)});
test('completing the last set of an exercise selects the next pending exercise after rest',()=>{const a=app();a.run("startFreeWorkout({exercise:'动作A',sets:'1',reps:'10',type:'bodyweight',weight:''});startFreeWorkout({exercise:'动作B',sets:'2',reps:'10',type:'bodyweight',weight:''});selectedExercise=0;completeSet(0);endRest()");assert.equal(a.run('selectedExercise'),1);assert.match(a.element('workout-content').innerHTML,/动作B/);assert.match(a.element('workout-content').innerHTML,/1\/2 组/)});
test('failed group save leaves the current group uncompleted',()=>{const a=app();a.run("startFreeWorkout({exercise:'深蹲',sets:'3',reps:'10',type:'bodyweight',weight:''})");a.context.localStorage.setItem=()=>{throw Error('quota')};a.run('completeSet(0)');assert.equal(a.run('draft.items[0].sets[0].done'),false);assert.equal(a.run('restEnd'),0)});

test('rest screen removes more controls and adding thirty seconds persists deadline',()=>{const a=app();a.run("startFreeWorkout({exercise:'深蹲',sets:'2',reps:'10',type:'bodyweight',weight:''})");assert.doesNotMatch(a.element('workout-content').innerHTML,/本组感受|感受与休息设置/);a.run('completeSet(0)');const before=a.run('restEnd');assert.doesNotMatch(a.element('workout-content').innerHTML,/更多操作/);assert.match(a.element('workout-content').innerHTML,/\+30s/);a.run('extendRest()');assert.equal(a.run('restEnd'),before+30000);assert.equal(JSON.parse(a.storage.get('nextstep.draft')).restEnd,before+30000)});
test('overall feedback is requested at finish and saved with a stopped end time',()=>{const a=app();a.run("startFreeWorkout({exercise:'深蹲',sets:'1',reps:'10',type:'bodyweight',weight:''});completeSet(0)");assert.match(a.element('workout-content').innerHTML,/这次训练感觉怎么样/);const stopped=a.run('draft.finishedAt');a.run("draft.feedback='吃力';finishWorkout()");assert.equal(a.run('records[0].feeling'),'吃力');assert.equal(a.run('records[0].endedAt'),stopped)});

test('zero kg weighted sets are rejected while bodyweight sets store no kg',()=>{const a=app();assert.equal(a.run("startFreeWorkout({exercise:'哑铃卧推',sets:'2',reps:'10',weight:'0'})"),false);a.run("startFreeWorkout({exercise:'哑铃卧推',sets:'2',reps:'10',weight:'5'});draft.items[0].sets[0].weight=0;completeSet(0)");assert.equal(a.run('draft.items[0].sets[0].done'),false);a.run('draft.items[0].sets[0].done=true;finishWorkout()');assert.equal(a.run('records.length'),0)});
test('plan reference uses actual previous same-exercise load and catalog fallback is positive',()=>{const a=app();assert.ok(a.run("recommendedWeight({name:'哑铃卧推'}).weight")>0);a.run("records=[{items:[{name:'哑铃卧推',sets:[{weight:12.5,done:true}]}]}]");assert.equal(a.run("recommendedWeight({name:'哑铃卧推'}).weight"),12.5);assert.equal(a.run("makeWorkoutItem({name:'俯卧撑',sets:2}).sets[0].weight"),null)});
test('exercise replacement retains completed sets and changes only remaining work',()=>{const a=app();a.run("startFreeWorkout({exercise:'哑铃卧推',sets:'3',reps:'10',weight:'5'});completeSet(0);endRest();replaceExercise('器械推胸')");assert.equal(a.run('draft.items[0].sets.length'),1);assert.equal(a.run('draft.items[0].sets[0].done'),true);assert.equal(a.run('draft.items[1].name'),'器械推胸');assert.equal(a.run('draft.items[1].sets.length'),2);assert.ok(a.run('draft.items[1].sets[0].weight')>0);assert.doesNotMatch(a.element('workout-content').innerHTML,/更多操作/);assert.doesNotMatch(a.element('workout-content').innerHTML,/长按结束/);a.run('toggleWorkoutPause()');assert.match(a.element('workout-content').innerHTML,/长按结束/)});
test('sports calorie estimate scales with duration and weight and persists its basis',()=>{const a=app();assert.equal(a.run("estimatedCalories('surf',60,70)"),210);assert.equal(a.run("estimatedCalories('swim-slow',60,70)"),406);assert.equal(a.run("estimatedCalories('stairs',30,70)"),238);assert.equal(a.run("estimatedCalories('surf',0,70)"),null);assert.equal(a.run("saveSport({sport:'surf',minutes:'60',weight:'70',date:localDate()})"),true);assert.equal(a.run('records[0].calories'),210);assert.equal(a.run('records[0].met'),3);assert.equal(a.run('records[0].sets'),0);assert.equal(a.run('records[0].volume'),0)});

test('hold to end waits for its threshold and short presses can be cancelled',()=>{const a=app();a.run("startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'2',reps:'10',weight:''});completeSet(0);endRest();toggleWorkoutPause()");let pending=null;a.context.setTimeout=fn=>{pending=fn;return 1};a.context.clearTimeout=()=>{pending=null};const button={isConnected:true,classList:{add(){},remove(){}}};a.context.holdTestButton=button;a.run('beginEndHold(holdTestButton)');assert.equal(a.run('draft.finishedAt'),undefined);a.run('cancelEndHold()');assert.equal(pending,null);a.run('beginEndHold(holdTestButton)');pending();assert.ok(a.run('draft.finishedAt')>0);assert.match(a.element('workout-content').innerHTML,/这次训练感觉怎么样/)});
test('plan progress excludes sports and free sessions and deduplicates dates',()=>{const a=app();a.run("records=[{date:localDate(),mode:'sport'},{date:localDate(),mode:'free'},{date:localDate(),mode:'plan'},{date:localDate(),mode:'plan'},{date:'2000-01-01',mode:'plan'}]");assert.equal(a.run('weeklyPlanProgress()'),1);a.run("records=[{date:localDate(),mode:'sport'}]");assert.equal(a.run('strengthToday()'),false);assert.equal(a.run('weeklyPlanProgress()'),0)});
test('last group edits preserve timing and undo restores a pending group',()=>{const a=app();a.run("startFreeWorkout({exercise:'哑铃划船',sets:'2',reps:'10',weight:'5'});completeSet(0)");const deadline=a.run('restEnd'),completed=a.run('draft.items[0].sets[0].completedAt');assert.equal(a.run("updateLastSet({weight:'7.5',reps:'12'})"),true);assert.equal(a.run('restEnd'),deadline);assert.equal(a.run('draft.items[0].sets[0].completedAt'),completed);assert.equal(a.run('draft.items[0].sets[0].weight'),7.5);a.context.localStorage.setItem=()=>{throw Error('quota')};assert.equal(a.run('updateLastSet(null,true)'),false);assert.equal(a.run('draft.items[0].sets[0].done'),true);a.context.localStorage.setItem=(k,v)=>a.storage.set(k,v);assert.equal(a.run('updateLastSet(null,true)'),true);assert.equal(a.run('restEnd'),0);assert.equal(a.run('pendingSet().setIndex'),0)});
test('undo final bodyweight group unfreezes feedback without losing start',()=>{const a=app();a.run("startFreeWorkout({exercise:'俯卧撑',sets:'1',reps:'10',type:'bodyweight'});completeSet(0)");const start=a.run('draft.startedAt');assert.equal(a.run("updateLastSet({reps:'15'})"),true);assert.equal(a.run('draft.items[0].sets[0].weight'),null);assert.equal(a.run('updateLastSet(null,true)'),true);assert.equal(a.run('draft.finishedAt'),undefined);assert.equal(a.run('draft.startedAt'),start)});
test('discard retains draft on removal failure and never deletes history',()=>{const a=app();a.run("startFreeWorkout({exercise:'俯卧撑',sets:'2',reps:'10',type:'bodyweight'});records=[{id:1,date:localDate(),name:'旧记录',minutes:10,sets:1,volume:0,exercises:1}]");a.context.localStorage.removeItem=()=>{throw Error('quota')};assert.equal(a.run('discardWorkout()'),false);assert.ok(a.run('draft'));a.context.localStorage.removeItem=k=>a.storage.delete(k);assert.equal(a.run('discardWorkout()'),true);assert.equal(a.run('draft'),null);assert.equal(a.run('records.length'),1);assert.equal(a.storage.has('nextstep.draft'),false)});
test('rest preference persists and active countdown is unchanged',()=>{const a=app();assert.equal(a.run('changeWorkoutRest(120)'),true);a.run("startFreeWorkout({exercise:'俯卧撑',sets:'2',reps:'10',type:'bodyweight'});completeSet(0)");const deadline=a.run('restEnd');assert.equal(a.run('draft.restSeconds'),120);assert.equal(a.run('changeWorkoutRest(180)'),true);assert.equal(a.run('restEnd'),deadline);assert.equal(a.run('changeWorkoutRest(12)'),false);a.context.localStorage.setItem=()=>{throw Error('quota')};assert.equal(a.run('changeWorkoutRest(60)'),false);assert.equal(a.run('draft.restSeconds'),180)});

test('recent missing steps identify latest date without shifting old steps into today',()=>{const a=app();a.context.window.NextStepAndroid={readHealthSteps(){}};healthSample(a,null,2000);a.run("healthSteps.days[4].steps=123;healthSteps.days[4].sources=['source'];");const html=a.run('healthCard()');assert.match(html,/今日暂无共享步数/);const date=a.run('healthSteps.days[4].date.slice(5)');assert.ok(html.includes('最新数据 '+date));assert.match(html,/—<small>今日步数/);assert.match(html,/读取范围包含今天/);});


test('saved workout survives failed draft cleanup without offering duplicate resume',()=>{const a=app();a.run("startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'1',reps:'10'});completeSet(0)");a.context.localStorage.removeItem=()=>{throw Error('denied')};a.run('finishWorkout()');const initial=Object.fromEntries([...a.storage].map(([k,v])=>[k,JSON.parse(v)])),b=app(initial);assert.equal(b.run('draft'),null);b.run('finishWorkout()');assert.equal(b.run('records.length'),1);assert.ok(b.run('records[0].workoutId'))});
test('legacy saved draft is reconciled without deleting unrelated draft',()=>{const a=app({'nextstep.records':[{id:1,startedAt:100,date:'2000-01-01',minutes:1,sets:1,volume:0}], 'nextstep.draft':{startedAt:100,items:[]}});assert.equal(a.run('draft'),null);const b=app({'nextstep.records':[{id:1,startedAt:100,date:'2000-01-01',minutes:1,sets:1,volume:0}], 'nextstep.draft':{startedAt:200,items:[]}});assert.equal(b.run('draft.startedAt'),200)});
test('name-only edit preserves seconds and original timestamps',()=>{const a=app();a.run("startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'1',reps:'10'});draft.startedAt=Date.now()-125000;completeSet(0);finishWorkout()");const before=a.run('({...records[0]})');a.context.editValues={name:'新名称',date:before.date,minutes:String(before.minutes),feeling:'合适','reps-0-0':'10'};assert.equal(a.run('updateRecord(String(records[0].id),editValues)'),true);assert.equal(a.run('records[0].seconds'),before.seconds);assert.equal(a.run('records[0].startedAt'),before.startedAt);assert.equal(a.run('records[0].endedAt'),before.endedAt);a.context.editValues.minutes='3';a.run('updateRecord(String(records[0].id),editValues)');assert.equal(a.run('records[0].seconds'),180)});
test('edited date retains workout identity for stale draft reconciliation',()=>{const a=app();a.run("startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'1',reps:'10'});completeSet(0)");const old=JSON.parse(a.storage.get('nextstep.draft'));a.run('finishWorkout();delete records[0].workoutId');a.context.editValues={name:'改日期',date:'2000-01-01',minutes:'1','reps-0-0':'10'};a.run('updateRecord(String(records[0].id),editValues)');const b=app({'nextstep.records':JSON.parse(a.storage.get('nextstep.records')),'nextstep.draft':old});assert.equal(b.run('draft'),null)});
test('invalid set input stays visible and does not rerender or persist',()=>{const a=app();a.run("startFreeWorkout({exercise:'哑铃划船',type:'weighted',sets:'2',reps:'10',weight:'5'})");const html=a.element('workout-content').innerHTML,persisted=a.storage.get('nextstep.draft');let invalid=false;const el={dataset:{set:'0',field:'weight'},value:'0',min:'0.5',max:'1000',setAttribute(){invalid=true},removeAttribute(){invalid=false}};a.context.inputProbe=el;a.run("persistSetInput({target:inputProbe,type:'change'})");assert.equal(el.value,'0');assert.equal(invalid,true);assert.equal(a.element('workout-content').innerHTML,html);assert.equal(a.storage.get('nextstep.draft'),persisted);el.value='7.5';a.run("persistSetInput({target:inputProbe,type:'input'})");assert.equal(invalid,false);assert.equal(a.run('draft.items[0].sets[0].weight'),7.5)});
test('bodyweight details and ended home state have meaningful labels',()=>{const a=app();a.run("startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'1',reps:'10'});completeSet(0)");assert.match(a.run('today()'),/训练已结束，待保存记录/);assert.match(a.run('today()'),/>保存训练</);a.run('finishWorkout();recordDialog(String(records[0].id))');const html=a.element('workout-content').innerHTML;assert.doesNotMatch(html,/<td>(null|undefined)</);assert.match(html,/<td>—</);assert.match(html,/<td>未反馈</)});
test('preparation and replacement dialogs provide return actions',()=>{const a=app();a.run('freeSetup()');assert.match(a.element('workout-content').innerHTML,/data-action="back-mode"/);a.run("startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'2',reps:'10'});swapDialog()");assert.match(a.element('workout-content').innerHTML,/data-action="back-workout"/);a.run('freeSetup()');assert.match(a.element('workout-content').innerHTML,/data-action="back-workout"/)});

test('plan day switch replaces only plan sections and restores selected focus',()=>{const a=app();a.run("saveProfile({...profileDefaults,name:'用户',height:'175',weight:'70',goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中'});render('plan')");const before=a.element('app').innerHTML;let replaced=[],focused=false;const nodes={'.plan-days':{replaceWith(node){replaced.push(node)}},'.wide-grid':{replaceWith(node){replaced.push(node)}},'[data-day="5"]':{focus(options){focused=options.preventScroll}}};a.element('app').querySelector=()=>({querySelector:selector=>nodes[selector]});a.context.document.createElement=()=>({content:{querySelector:selector=>selector}});a.run('changePlanDay(5)');assert.equal(a.run('planDay'),5);assert.equal(a.element('app').innerHTML,before);assert.deepEqual(replaced,['.plan-days','.wide-grid']);assert.equal(focused,true)});
test('mixed gym session counts once and uses wall-clock time',()=>{const a=app();a.run("startSession();draft.startedAt=Date.now()-5400000;startFreeWorkout({exercise:'哑铃划船',sets:'1',reps:'12',weight:'10'});completeSet(0);startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'1',reps:'15'});completeSet(0);saveSport({sport:'walk',minutes:'20',weight:'70',distance:'3000',date:localDate(new Date(draft.startedAt))});saveSport({sport:'swim-slow',minutes:'15',weight:'70',distance:'500',date:localDate(new Date(draft.startedAt))})");assert.equal(a.run('records.length'),0);assert.equal(a.run('draft.activities.length'),2);assert.equal(a.run('draft.finishedAt'),undefined);a.run('finishReview()');const end=a.run('draft.finishedAt');a.run('finishWorkout()');assert.equal(a.run('summary(rangeRecords()).count'),1);assert.equal(a.run('records[0].minutes'),90);assert.equal(a.run('records[0].endedAt'),end);assert.equal(a.run('records[0].sets'),2);assert.equal(a.run('records[0].volume'),120);assert.equal(a.run('records[0].exercises'),4);a.run('recordDialog(String(records[0].id))');assert.match(a.element('workout-content').innerHTML,/3000 米/);assert.match(a.element('workout-content').innerHTML,/500 米/)});
test('sport-only session survives reload and does not advance strength schedule',()=>{const a=app();a.run("startSession();saveSport({sport:'swim-slow',minutes:'15',weight:'70',date:localDate()})");const b=app(Object.fromEntries([...a.storage].map(([k,v])=>[k,JSON.parse(v)])));assert.equal(b.run('draft.startedAt'),a.run('draft.startedAt'));b.run('workoutDialog()');assert.equal(b.run('draft.finishedAt'),undefined);b.run('finishReview();finishWorkout()');assert.equal(b.run('records.length'),1);assert.equal(b.run('records[0].sets'),0);assert.equal(b.run('records[0].volume'),0);assert.equal(b.run('records[0].exercises'),1);assert.equal(b.run('strengthToday()'),false)});
test('session start and append failures retain retry state',()=>{const a=app();a.context.localStorage.setItem=()=>{throw Error('quota')};assert.equal(a.run('startSession()'),false);assert.equal(a.run('draft'),null);a.context.localStorage.setItem=(k,v)=>a.storage.set(k,v);a.run('startSession()');a.context.localStorage.setItem=()=>{throw Error('quota')};assert.equal(a.run("saveSport({sport:'walk',minutes:'10',weight:'70',date:localDate()})"),false);assert.equal(a.run('draft.activities.length'),0);a.context.localStorage.setItem=(k,v)=>a.storage.set(k,v);a.run("saveSport({sport:'walk',minutes:'10',weight:'70',date:localDate()});finishReview()");a.context.localStorage.setItem=()=>{throw Error('quota')};a.run('finishWorkout()');assert.equal(a.run('records.length'),0);assert.ok(a.run('draft.finishedAt'));a.context.localStorage.setItem=(k,v)=>a.storage.set(k,v);a.run('finishWorkout();finishWorkout()');assert.equal(a.run('records.length'),1)});
test('session validates sport distance and consistent date',()=>{const a=app();a.run('startSession()');for(const distance of ['0','-1','1.5','Infinity','1000001'])assert.equal(a.run("saveSport({sport:'walk',minutes:'10',weight:'70',distance:"+JSON.stringify(distance)+",date:localDate()})"),false);assert.equal(a.run("saveSport({sport:'walk',minutes:'10',weight:'70',date:'2000-01-01'})"),false);assert.equal(a.run('draft.activities.length'),0)});
test('plan session can append strength and sport while keeping plan identity',()=>{const a=app();a.run("saveProfile({...profileDefaults,name:'测试',height:'175',weight:'70',goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中'});startWorkout()");assert.equal(a.run("startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'1',reps:'15'})"),true);assert.equal(a.run("saveSport({sport:'walk',minutes:'10',weight:'70',date:localDate()})"),true);a.run('finishReview();finishWorkout()');assert.equal(a.run('records[0].mode'),'plan');assert.equal(a.run('records[0].activities.length'),1)});
test('editing session sports preserves overall duration and count',()=>{const a=app();a.run("startSession();draft.startedAt=Date.now()-3600000;saveSport({sport:'walk',minutes:'10',weight:'70',distance:'800',date:localDate(new Date(draft.startedAt))});finishReview();finishWorkout()");const before=a.run('records[0].seconds');assert.equal(a.run("updateRecord(String(records[0].id),{name:'健身房训练',date:localDate(),minutes:'60','activity-minutes-0':'20','activity-weight-0':'80','activity-distance-0':'1600'})"),true);assert.equal(a.run('records[0].seconds'),before);assert.equal(a.run('records[0].activities[0].minutes'),20);assert.equal(a.run('records[0].activities[0].distance'),1600);assert.equal(a.run('records[0].exercises'),1);assert.equal(a.run('summary(rangeRecords()).minutes'),60);assert.equal(a.run('summary(rangeRecords()).count'),1)});
test('legacy aggregate-only record edits retain exercise totals',()=>{const a=app();a.run("records=[{id:1,date:localDate(),name:'旧训练',minutes:20,sets:8,volume:500,exercises:3,items:[]}]");assert.equal(a.run("updateRecord('1',{name:'旧训练改名',date:localDate(),minutes:'20'})"),true);assert.equal(a.run('records[0].exercises'),3);assert.equal(a.run('records[0].sets'),8);assert.equal(a.run('records[0].volume'),500)});
test('sport alone does not count as completing a planned strength session',()=>{const a=app();a.run("records=[{date:localDate(),mode:'plan',activities:[{name:'游泳'}],items:[{sets:[{done:false}]}]}]");assert.equal(a.run('weeklyPlanProgress()'),0);a.run('records[0].items[0].sets[0].done=true');assert.equal(a.run('weeklyPlanProgress()'),1)});
test('project lookup combines name, muscle and equipment keywords with category filtering',()=>{const a=app();assert.deepEqual(Array.from(a.run("matchingProjects('free','哑铃 背部').map(e=>e.name)")),['哑铃划船','哑铃俯身反向飞鸟']);assert.ok(a.run("matchingProjects('free','胸部','徒手').every(e=>e.group==='徒手')"));assert.equal(a.run("matchingProjects('free','背部','杠铃').length"),1);assert.equal(a.run("matchingProjects('free','不存在的动作').length"),0)});
test('sport lookup supports everyday running and stairs aliases without changing MET values',()=>{const a=app();assert.equal(a.run("matchingProjects('sport','跑步')[0].key"),'jog');assert.equal(a.run("matchingProjects('sport','楼梯').length"),3);assert.equal(a.run("matchingProjects('sport','游泳','游泳').length"),4);assert.equal(a.run("estimatedCalories(matchingProjects('sport','跑步')[0].key,60,70)"),525)});
test('recent catalog projects derive only from completed strength and recorded sports',()=>{const a=app();a.run("records=[{items:[{name:'哑铃划船',sets:[{done:true}]},{name:'杠铃卧推',sets:[{done:false}]}],activities:[{activityCode:'18240'}]}]");assert.equal(a.run("matchingProjects('free')[0].name"),'哑铃划船');assert.equal(a.run("matchingProjects('sport')[0].key"),'swim-slow');assert.equal(a.run("recentProjectKeys('free').includes('杠铃卧推')"),false);a.run("draft={items:[{name:'俯卧撑',sets:[{done:true}]}],activities:[]}");assert.equal(a.run("matchingProjects('free')[0].name"),'俯卧撑')});
test('catalog search is read-only and no-match guidance supports custom exercises',()=>{const a=app();const before=Array.from(a.storage);assert.match(a.run("projectResults('free','<script>')"),/自定义动作/);assert.doesNotMatch(a.run("projectResults('free','<script>')"),/<script>/);a.run("projectPicker('free');matchingProjects('swap','背部');projectPicker('sport')");assert.deepEqual(Array.from(a.storage),before);assert.equal(a.run('draft'),null)});
test('filter refresh only replaces search results and keeps form inputs intact',()=>{const a=app();a.run('freeSetup()');a.element('project-search-free').value='划船';a.element('project-group-free').value='哑铃';a.element('free-reps').value='17';const form=a.element('workout-content').innerHTML;a.run("updateProjectPicker('free')");assert.equal(a.element('free-reps').value,'17');assert.equal(a.element('workout-content').innerHTML,form);assert.match(a.element('project-results-free').innerHTML,/哑铃划船/);assert.doesNotMatch(a.element('project-results-free').innerHTML,/杠铃划船/)});
test('search blur does not rebuild results before the selected button receives click',()=>{const a=app();a.element('project-results-free').innerHTML='selected button';a.context.searchInput={dataset:{projectSearch:'free'}};a.run("persistSetInput({target:searchInput,type:'change'})");assert.equal(a.element('project-results-free').innerHTML,'selected button')});

test('pause persists frozen rest, locks completion and resumes remaining countdown after restart',()=>{const a=app();a.run("startSession();startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'3',reps:'10'});completeSet(0);toggleWorkoutPause()");const paused=JSON.parse(a.storage.get('nextstep.draft'));assert.equal(paused.paused,true);assert.ok(paused.pausedRest>0);assert.equal(a.run('restEnd'),0);a.run('completeSet(1);endRest();extendRest()');assert.equal(a.run('draft.items[0].sets[1].done'),false);assert.equal(a.run('draft.pausedRest'),paused.pausedRest);const b=app({'nextstep.draft':paused});b.run('workoutDialog()');assert.match(b.element('workout-content').innerHTML,/训练已暂停/);assert.doesNotMatch(b.element('workout-content').innerHTML,/current-set-form/);assert.equal(b.run('toggleWorkoutPause()'),true);assert.ok(b.run('Math.abs(restEnd-Date.now()-'+paused.pausedRest+')')<100);assert.equal(b.run('draft.paused'),false);assert.equal(b.run('draft.pausedRest'),undefined)});
test('failed pause and resume writes keep state and deadline retryable',()=>{const a=app();a.run("startSession();startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'2',reps:'10'});completeSet(0)");const before=a.run('restEnd');a.context.localStorage.setItem=()=>{throw Error('quota')};assert.equal(a.run('toggleWorkoutPause()'),false);assert.equal(a.run('restEnd'),before);assert.equal(a.run('draft.paused'),undefined);a.context.localStorage.setItem=(k,v)=>a.storage.set(k,v);a.run('toggleWorkoutPause()');const remaining=a.run('draft.pausedRest');a.context.localStorage.setItem=()=>{throw Error('quota')};assert.equal(a.run('toggleWorkoutPause()'),false);assert.equal(a.run('draft.paused'),true);assert.equal(a.run('draft.pausedRest'),remaining);assert.equal(a.run('restEnd'),0)});
test('ending hold is unavailable until paused and resume cancels a pending hold',()=>{const a=app();a.run("startSession();startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'2',reps:'10'});completeSet(0);endRest()");let pending=null;a.context.setTimeout=fn=>{pending=fn;return 1};a.context.clearTimeout=()=>{pending=null};a.context.pauseHoldButton={isConnected:true,classList:{add(){},remove(){}}};a.run('beginEndHold(pauseHoldButton)');assert.equal(pending,null);a.run('toggleWorkoutPause();beginEndHold(pauseHoldButton)');assert.equal(typeof pending,'function');a.run('toggleWorkoutPause()');assert.equal(pending,null);assert.equal(a.run('draft.finishedAt'),undefined)});

test('touch hold cancels when captured pointer moves outside and cannot restart by sliding back',()=>{const a=app();a.run("startSession();startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'2',reps:'10'});completeSet(0);endRest();toggleWorkoutPause()");let pending=null;a.context.setTimeout=fn=>{pending=fn;return 1};a.context.clearTimeout=()=>{pending=null};a.context.touchHoldButton={isConnected:true,classList:{add(){},remove(){}},getBoundingClientRect(){return{left:10,right:110,top:20,bottom:80}}};a.run('beginEndHold(touchHoldButton,7);moveEndHold({pointerId:8,clientX:0,clientY:0})');assert.equal(typeof pending,'function');a.run('moveEndHold({pointerId:7,clientX:50,clientY:40})');assert.equal(typeof pending,'function');a.run('moveEndHold({pointerId:7,clientX:9,clientY:40})');assert.equal(pending,null);assert.equal(a.run('holdButton'),null);a.run('moveEndHold({pointerId:7,clientX:50,clientY:40})');assert.equal(pending,null);assert.equal(a.run('draft.finishedAt'),undefined)});
test('successful touch hold consumes its release click and leaves the next gesture usable',()=>{const a=app();a.run("startSession();startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'2',reps:'10'});completeSet(0);endRest();toggleWorkoutPause()");let pending=null;a.context.setTimeout=fn=>{pending=fn;return 1};a.context.clearTimeout=()=>{pending=null};a.context.touchHoldButton={isConnected:true,classList:{add(){},remove(){}}};a.run('beginEndHold(touchHoldButton,7)');pending();assert.ok(a.run('draft.finishedAt'));assert.equal(a.element('workout-dialog').open,true);a.run('cancelEndHold()');let prevented=0,stopped=0;a.context.releaseClick={preventDefault(){prevented++},stopImmediatePropagation(){stopped++}};a.run('suppressEndHoldClick(releaseClick)');assert.equal(prevented,1);assert.equal(stopped,1);a.run('suppressEndHoldClick(releaseClick)');assert.equal(prevented,1);a.run('suppressEndClick=true');a.listeners.get('pointerdown')[0]({isPrimary:true,button:0,pointerId:8,target:{closest(){return null}}});assert.equal(a.run('suppressEndClick'),false);assert.equal(a.element('workout-dialog').open,true)});
test('touch pointer cancellation clears a pending ending hold without finishing',()=>{const a=app();a.run("startSession();startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'2',reps:'10'});completeSet(0);endRest();toggleWorkoutPause()");let pending=null;a.context.setTimeout=fn=>{pending=fn;return 1};a.context.clearTimeout=()=>{pending=null};a.context.touchHoldButton={isConnected:true,classList:{add(){},remove(){}}};a.run('beginEndHold(touchHoldButton,7)');a.listeners.get('pointercancel')[0]({pointerId:8});assert.equal(typeof pending,'function');a.listeners.get('pointercancel')[0]({pointerId:7});assert.equal(pending,null);assert.equal(a.run('draft.finishedAt'),undefined)});

test('training tool navigation separates tasks and preserves paused draft and resting deadline',()=>{const a=app();a.run("startSession();startFreeWorkout({exercise:'哑铃卧推',sets:'3',reps:'10',weight:'5'});completeSet(0);toggleWorkoutPause()");const stored=a.storage.get('nextstep.draft');const click=action=>a.listeners.get('click')[0]({target:{closest(){return{dataset:{action}}}}});click('workout-options');let html=a.element('workout-content').innerHTML;assert.match(html,/训练工具/);assert.doesNotMatch(html,/id="workout-rest"|放弃本次训练|id="free-form"/);click('workout-add');assert.match(a.element('workout-content').innerHTML,/力量 \/ 次数训练/);click('tool-strength');assert.match(a.element('workout-content').innerHTML,/data-action="workout-add"/);assert.doesNotMatch(a.element('workout-content').innerHTML,/id="workout-rest"/);click('workout-add');click('tool-sport');assert.match(a.element('workout-content').innerHTML,/data-action="workout-add"/);click('workout-add');click('workout-options');click('tool-swap');assert.match(a.element('workout-content').innerHTML,/data-action="workout-options"/);click('workout-options');click('back-workout');assert.equal(a.storage.get('nextstep.draft'),stored);assert.equal(a.run('draft.paused'),true);assert.equal(a.run('restEnd'),0)});
test('tool corrections and destructive confirmations have explicit return paths without changing data on cancel',()=>{const a=app();a.run("startSession();startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'3',reps:'10'});completeSet(0)");const stored=a.storage.get('nextstep.draft');const click=action=>a.listeners.get('click')[0]({target:{closest(){return{dataset:{action}}}}});click('tool-edit-last');assert.match(a.element('workout-content').innerHTML,/data-action="workout-options"/);click('undo-last-prompt');assert.match(a.element('workout-content').innerHTML,/撤销这一组完成？/);assert.equal(a.run('draft.items[0].sets[0].done'),true);click('back-edit-last');assert.match(a.element('workout-content').innerHTML,/id="last-set-form"/);assert.match(a.element('workout-content').innerHTML,/data-action="workout-options"/);click('workout-options');click('workout-settings');assert.doesNotMatch(a.element('workout-content').innerHTML,/添加训练项目|id="last-set-form"/);click('tool-discard');assert.match(a.element('workout-content').innerHTML,/data-action="workout-settings"/);click('workout-settings');assert.equal(a.storage.get('nextstep.draft'),stored);assert.equal(a.run('records.length'),0)});
test('finished feedback tools hide adding and replacement and correction preserves the stopped end',()=>{const a=app();a.run("startSession();startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'2',reps:'10'});completeSet(0);endRest();finishReview()");const end=a.run('draft.finishedAt');a.run('workoutOptions()');const html=a.element('workout-content').innerHTML;assert.match(html,/返回反馈/);assert.doesNotMatch(html,/data-action="workout-add"|data-action="tool-swap"/);a.run('workoutAddDialog()');assert.equal(a.element('workout-content').innerHTML,html);a.run("editLastSet('workout-options')");assert.match(a.element('workout-content').innerHTML,/保存并返回反馈/);assert.equal(a.run("updateLastSet({reps:'12'})"),true);assert.equal(a.run('draft.finishedAt'),end);assert.equal(a.run('draft.items[0].sets[0].reps'),12);assert.match(a.element('workout-content').innerHTML,/这次训练感觉怎么样/)});
test('empty training tools omit unavailable correction actions and addition returns to paused player',()=>{const a=app();a.run('startSession();workoutOptions()');const html=a.element('workout-content').innerHTML;assert.doesNotMatch(html,/data-action="tool-edit-last"|data-action="tool-swap"/);a.run('toggleWorkoutPause()');const began=a.run('draft.startedAt');assert.equal(a.run("startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'2',reps:'10'})"),true);assert.equal(a.run('draft.startedAt'),began);assert.equal(a.run('draft.paused'),true);assert.match(a.element('workout-content').innerHTML,/训练已暂停/)});
test('undoing a completed group while paused clears frozen rest before continuing',()=>{const a=app();a.run("startSession();startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'3',reps:'10'});completeSet(0);toggleWorkoutPause()");assert.ok(a.run('draft.pausedRest')>0);a.run('undoLastPrompt()');assert.equal(a.run('draft.items[0].sets[0].done'),true);assert.equal(a.run('updateLastSet(null,true)'),true);assert.equal(a.run('draft.paused'),true);assert.equal(a.run('draft.pausedRest'),undefined);a.run('toggleWorkoutPause()');assert.equal(a.run('restEnd'),0);assert.equal(a.run('draft.items[0].sets[0].done'),false)});
test('failed tool rest change restores the saved selection and exposes a retry message',()=>{const a=app();a.run('startSession();workoutSettings()');const before=a.storage.get('nextstep.draft');a.context.localStorage.setItem=()=>{throw Error('quota')};a.context.toolRestInput={id:'workout-rest',value:'120',dataset:{}};a.run("persistSetInput({target:toolRestInput,type:'change'})");assert.equal(a.context.toolRestInput.value,'90');assert.match(a.element('workout-rest-status').textContent,/保存失败/);assert.equal(a.storage.get('nextstep.draft'),before);a.context.localStorage.setItem=(k,v)=>a.storage.set(k,v);a.context.toolRestInput.value='120';a.run("persistSetInput({target:toolRestInput,type:'change'})");assert.equal(a.run('draft.restSeconds'),120);assert.match(a.element('workout-rest-status').textContent,/已保存/)});

test('Google Fit shared steps retain raw source, persist once and do not inflate training totals',()=>{const a=app();a.run("window.NextStepAndroid={readHealthSteps(){},openGoogleFit(){}};window.nextstepHealthResult({status:'ready',days:savedStepDays().map(d=>({...d,steps:123,sources:['com.google.android.apps.fitness']})),sources:['com.google.android.apps.fitness'],syncedAt:1000})");assert.match(a.run('healthCard()'),/本次聚合结果包含 Google Fit/);assert.equal(a.run('activityRecords.length'),7);assert.equal(a.run('activityRecords[0].sources[0]'),'com.google.android.apps.fitness');assert.equal(a.run('summary(rangeRecords()).count'),0);assert.match(a.run('stepHistory()'),/来源：Google Fit/);a.run("window.nextstepHealthResult({status:'permission',message:'未授权'})");assert.doesNotMatch(a.run('googleFitSync()'),/本次聚合结果包含/);assert.equal(a.run('activityRecords.length'),7)});
test('Google Fit entry calls only the fixed native launcher and handles older bridges',()=>{const a=app();let opened=0;a.context.window.NextStepAndroid={readHealthSteps(){},openGoogleFit(){opened++}};assert.match(a.run('googleFitSync()'),/google-fit-open/);a.listeners.get('click')[0]({target:{closest(){return {dataset:{action:'google-fit-open'}}}}});assert.equal(opened,1);a.context.window.NextStepAndroid={readHealthSteps(){}};assert.doesNotMatch(a.run('googleFitSync()'),/google-fit-open/);assert.equal(a.run('records.length'),0)});

test('plan preferences open only the selected field and preserve data until saving',()=>{const a=app();a.run("saveProfile({...profileDefaults,name:'用户',height:'175',weight:'70',goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中'})");const before=a.storage.get('nextstep.profile');for(const key of ['goal','frequency','duration','equipment']){assert.match(a.run('plan()'),new RegExp('data-plan-preference="'+key+'"'));a.listeners.get('click')[0]({target:{closest(){return {dataset:{planPreference:key}}}}});assert.match(a.element('workout-content').innerHTML,new RegExp('data-preference="'+key+'"'));assert.match(a.element('workout-content').innerHTML,key==='frequency'||key==='duration'?/type="number"/:/type="radio"/);assert.doesNotMatch(a.element('workout-content').innerHTML,/id="profile-form"/);assert.equal(a.storage.get('nextstep.profile'),before)}});
test('single preference changes regenerate the plan and retain draft, records and selected day',()=>{const a=app();a.run("saveProfile({...profileDefaults,name:'用户',height:'175',weight:'70',goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中'});startSession();planDay=5;profile.restSeconds=120;records=[{id:1,name:'既有记录'}]");const draft=a.run('JSON.stringify(draft)'),records=a.run('JSON.stringify(records)');for(const [key,value] of [['goal','减脂'],['frequency','每周 5 次'],['duration','60'],['equipment','哑铃']]){a.context.preferenceKey=key;a.context.preferenceValue=value;assert.equal(a.run('savePlanPreference(preferenceKey,preferenceValue)'),true);assert.equal(a.run('profile[preferenceKey]'),value);assert.equal(a.run('JSON.stringify(draft)'),draft);assert.equal(a.run('JSON.stringify(records)'),records);assert.equal(a.run('planDay'),5);assert.equal(a.run('profile.restSeconds'),120)}assert.equal(a.run('profile.trainingPlan.days.filter(d=>d.items.length).length'),5);assert.ok(a.run("profile.trainingPlan.days[0].items.every(e=>e.name.includes('哑铃'))"));assert.equal(JSON.parse(a.storage.get('nextstep.profile')).equipment,'哑铃')});
test('failed and invalid preference saves retain the old profile and retryable choices',()=>{const a=app();a.run("saveProfile({...profileDefaults,name:'用户',height:'175',weight:'70',goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中'});openPlanPreference('frequency');planDay=5");const before=a.run('JSON.stringify(profile)'),html=a.element('workout-content').innerHTML;a.context.localStorage.setItem=()=>{throw Error('quota')};assert.equal(a.run("savePlanPreference('frequency','每周 5 次')"),false);assert.equal(a.run('JSON.stringify(profile)'),before);assert.equal(a.run('planDay'),5);assert.equal(a.element('workout-content').innerHTML,html);for(const key of ['name','__proto__','toString'])assert.equal(a.run('savePlanPreference('+JSON.stringify(key)+',"减脂")'),false);assert.equal(a.run("savePlanPreference('duration','Infinity')"),false);a.context.localStorage.setItem=(k,v)=>a.storage.set(k,v);assert.equal(a.run("savePlanPreference('frequency','每周 5 次')"),true);assert.equal(a.run('profile.frequency'),'每周 5 次')});

test('custom frequency and duration persist, reload, and produce the requested training days',()=>{for(const count of [1,2,3,4,5,6,7]){const a=app();assert.equal(a.run("saveProfile({...profileDefaults,name:'用户',height:'175',weight:'70',goal:'增肌',frequency:'"+count+"',lifestyle:'久坐为主',experience:'有训练基础',duration:'37',equipment:'徒手 / 家中'})"),true);assert.equal(a.run('profile.trainingPlan.days.filter(d=>d.items.length).length'),count);const b=app({'nextstep.profile':JSON.parse(a.storage.get('nextstep.profile'))});assert.equal(b.run('profile.frequency'),'每周 '+count+' 次');assert.equal(b.run('profile.duration'),'37');assert.equal(b.run("savePlanPreference('duration','75')"),true);assert.equal(b.run('profile.duration'),'75');assert.equal(b.run("savePlanPreference('frequency','6')"),true);assert.equal(b.run('profile.trainingPlan.days.filter(d=>d.items.length).length'),6)}});
test('custom plan input rejects invalid values without changing stored data',()=>{const a=app();a.run("saveProfile({...profileDefaults,name:'用户',height:'175',weight:'70',goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中'})");const before=a.storage.get('nextstep.profile');for(const key of ['frequency','duration'])for(const value of ['', '0','-1','1.5','Infinity','NaN','1e2',key==='frequency'?'8':'241']){a.context.invalidKey=key;a.context.invalidValue=value;assert.equal(a.run('savePlanPreference(invalidKey,invalidValue)'),false);assert.equal(a.run('saveProfile({...profile,[invalidKey]:invalidValue})'),false);assert.equal(a.storage.get('nextstep.profile'),before)}assert.equal(a.run("savePlanPreference('duration','1')"),true);assert.ok(a.run('profile.trainingPlan.days.find(d=>d.items.length).items.length<=3'));assert.equal(a.run("savePlanPreference('duration','240')"),true)});

test('journal defaults to recent history and sorts pages without altering persisted records',()=>{const a=app();a.run("records=Array.from({length:24},(_,i)=>({id:i+1,date:localDate(new Date(Date.now()-i*86400000)),name:'记录'+i,minutes:30,sets:1,exercises:1,volume:100})).reverse()");const before=a.run('JSON.stringify(records)');assert.match(a.run('training()'),/id="journal-panel-history"[^>]*aria-labelledby="journal-view-history" >/);assert.match(a.run('training()'),/id="journal-panel-progress"[^>]*hidden/);assert.equal((a.run('journalHistory()').match(/class="history-row"/g)||[]).length,10);assert.ok(a.run('journalHistory()').indexOf('记录0')<a.run('journalHistory()').indexOf('记录1'));a.run('historyLimit=20');assert.equal((a.run('journalHistory()').match(/class="history-row"/g)||[]).length,20);assert.equal(a.run('JSON.stringify(records)'),before);a.run("render('trends')");assert.equal(a.run('journalView'),'progress')});
test('journal switching only changes visibility and preserves data and range',()=>{const a=app();a.run("render('training');period='month'");const before=a.element('app').innerHTML,buttons=['history','progress','activity'].map(key=>({dataset:{journalView:key},setAttribute(k,v){this.pressed=v}})),panels=buttons.map(b=>({dataset:{journalPanel:b.dataset.journalView},hidden:false}));let focus=false;a.context.document.querySelectorAll=s=>s==='[data-journal-view]'?buttons:panels;a.context.document.querySelector=()=>({focus(options){focus=options.preventScroll}});a.listeners.get('click')[0]({target:{closest(){return {dataset:{journalView:'activity'}}}}});assert.deepEqual(panels.map(p=>p.hidden),[true,true,false]);assert.deepEqual(buttons.map(b=>b.pressed),['false','false','true']);assert.equal(a.run('period'),'month');assert.equal(a.element('app').innerHTML,before);assert.equal(focus,true);a.run("changeJournalView('bad')");assert.equal(a.run('journalView'),'activity')});

test('combined home distinguishes rest, training and completed states without replacing rest with next workout',()=>{const a=app();a.run("saveProfile({...profileDefaults,name:'用户',height:'175',weight:'70',goal:'增肌',frequency:'每周 3 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中'});profile.trainingPlan.days[(new Date().getDay()+6)%7]={name:'休息与自由活动',items:[]}");assert.match(a.run('today()'),/今天安排休息与恢复/);assert.match(a.run('today()'),/本周计划/);assert.match(a.run('today()'),/data-plan-preference="frequency"/);assert.doesNotMatch(a.run('today()'),/下一次训练/);a.run("profile.trainingPlan.days[(new Date().getDay()+6)%7]={name:'今日动作',items:nextSession().items}");assert.match(a.run('today()'),/data-action="today-plan"/);a.run("records=[{date:localDate(),minutes:10,sets:1,volume:100}]");assert.match(a.run('today()'),/今日训练已记录/);assert.doesNotMatch(a.run('today()'),/data-action="today-plan"/)});
test('today start uses today plan even after previewing another day and old plan routes use combined home',()=>{const a=app();a.run("saveProfile({...profileDefaults,name:'用户',height:'175',weight:'70',goal:'增肌',frequency:'每周 7 次',lifestyle:'久坐为主',experience:'刚开始',duration:'30',equipment:'徒手 / 家中'});profile.trainingPlan.days[(new Date().getDay()+6)%7].name='今天专属';planDay=((new Date().getDay()+6)%7+1)%7;render('today')");a.listeners.get('click')[0]({target:{closest(){return {dataset:{action:'today-plan'}}}}});assert.equal(a.run('draft.name'),'今天专属');assert.match(a.run('today()'),/继续训练/);a.run("navigate('plan')");assert.equal(a.run('currentPage'),'today');assert.equal(a.context.location.hash,'today');assert.equal(a.run('pages.length'),2)});

test('home keeps plan collapsed until requested and moves statistics to the journal',()=>{const a=app();assert.match(a.run('today()'),/id="home-plan-details"[^>]* ><summary>/);assert.doesNotMatch(a.run('today()'),/home-statistics|stats-grid/);assert.match(a.run('today()'),/data-action="view-progress"/);a.listeners.get('toggle')[0]({target:{id:'home-plan-details',open:true}});assert.match(a.run('today()'),/id="home-plan-details"[^>]* open/);a.listeners.get('click')[0]({target:{closest(){return {dataset:{action:'view-progress'}}}}});assert.equal(a.run('currentPage'),'training');assert.equal(a.run('journalView'),'progress');assert.equal(a.run('records.length'),0);assert.equal(a.run('draft'),null)});

test('mode selection has no rest setting and explicit action rest stays with its exercise',()=>{const a=app();a.run('workoutModeDialog()');assert.doesNotMatch(a.element('workout-content').innerHTML,/workout-rest|组间休息/);a.run("startSession();startFreeWorkout({exercise:'俯卧撑',type:'bodyweight',sets:'2',reps:'10'});startFreeWorkout({exercise:'深蹲',type:'bodyweight',sets:'2',reps:'10'});selectedExercise=0;changeWorkoutRest(120)");assert.equal(a.run('draft.items[0].restSeconds'),120);assert.equal(a.run('draft.items[1].restSeconds'),90);a.run('selectedExercise=0;completeSet(0)');assert.ok(a.run('Math.abs(restEnd-Date.now()-120000)')<100);const b=app({'nextstep.draft':JSON.parse(a.storage.get('nextstep.draft'))});assert.equal(b.run('draft.items[0].restSeconds'),120);assert.equal(b.run('draft.items[1].restSeconds'),90)});

test('visual body and sport categories combine with search and equipment without modifying history',()=>{const a=app();const before=Array.from(a.storage);assert.ok(a.run("matchingProjects('free','','哑铃','arms').some(e=>e.name==='哑铃弯举')"));assert.ok(a.run("matchingProjects('free','','','hips').some(e=>e.name==='臀桥')"));assert.ok(a.run("matchingProjects('free','硬拉','','legs').every(e=>projectCategory('free',e.key)==='legs')"));assert.equal(a.run("matchingProjects('sport','','','swim').length"),4);assert.equal(a.run("matchingProjects('sport','','','water').length"),4);assert.equal(a.run("matchingProjects('sport','跑步','','run')[0].key"),'jog');assert.deepEqual(Array.from(a.storage),before)});
test('common projects use completed activity and do not invent starter history',()=>{const a=app();assert.equal(a.run("frequentProjects('free').length"),0);assert.match(a.run("projectPicker('free')"),/按身体部位|常练项目/);a.run("records=[{items:[{name:'哑铃弯举',sets:[{done:true}]},{name:'哑铃卧推',sets:[{done:false}]}],activities:[{activityCode:'18240'}]}]");assert.deepEqual(Array.from(a.run("frequentProjects('free').map(e=>e.key)")),['哑铃弯举']);assert.equal(a.run("frequentProjects('sport')[0].key"),'swim-slow');assert.match(a.run("projectPicker('sport')"),/按运动类型/)});

test('every built-in strength and sport has a finite animated movement definition',()=>{const a=app();assert.equal(a.run('exerciseCatalog.length+sports.length'),75);for(const key of Array.from(a.run('[...exerciseCatalog.map(e=>e.name),...sports.map(e=>e.id)]'))){a.context.motionKey=key;assert.equal(a.run('!!motionDefinitions[motionKey]'),true,key);assert.equal(a.run('motionPoses[motionDefinitions[motionKey].from].every(Number.isFinite)&&motionPoses[motionDefinitions[motionKey].to].every(Number.isFinite)'),true,key);assert.match(a.run('movementDrawing(motionKey)'),/<animate /,key)}a.context.window.matchMedia=()=>({matches:true});assert.doesNotMatch(a.run("movementDrawing('哑铃弯举')"),/<animate /)});
test('custom library saves a reusable categorized action without changing plan or training data',()=>{const a=app();const before=a.run('JSON.stringify(profile.trainingPlan)');assert.equal(a.run("saveCustomExercise({name:'我的划船',type:'weighted',muscle:'背部'})"),true);assert.equal(a.run('JSON.stringify(profile.trainingPlan)'),before);assert.equal(a.run('records.length'),0);assert.equal(a.run('draft'),null);assert.equal(a.run("matchingProjects('free','我的','','back')[0].key"),'我的划船');const b=app({'nextstep.profile':JSON.parse(a.storage.get('nextstep.profile'))});assert.equal(b.run("exerciseInfo({name:'我的划船'}).custom"),true);assert.equal(b.run("saveCustomExercise({name:'我的划船',type:'bodyweight',muscle:'核心'})"),true);assert.equal(b.run('profile.customExercises.length'),1);const old=b.storage.get('nextstep.profile');b.context.localStorage.setItem=()=>{throw Error('quota')};assert.equal(b.run("saveCustomExercise({name:'失败动作',type:'weighted',muscle:'胸部'})"),false);assert.equal(b.storage.get('nextstep.profile'),old);assert.equal(b.run('profile.customExercises.length'),1);assert.equal(b.run("saveCustomExercise({name:'哑铃弯举',type:'weighted',muscle:'手臂'})"),false)});

test('body picker is a single segmented figure and custom animation status is honest',()=>{const a=app();assert.match(a.run("projectPicker('free')"),/class="brick-figure"/);assert.match(a.run("projectPicker('free')"),/id="project-results-free" hidden/);assert.match(a.run("movementDrawing('未知动作')"),/暂无内置示意动画/);assert.doesNotMatch(a.run("movementDrawing('未知动作')"),/<animate/)});

test('equipment choices are a separate decision and animated matching cards reflect available catalog only',()=>{const a=app();const html=a.run("equipmentChoices('free','arms')");assert.match(html,/data-project-equipment="徒手"/);assert.match(html,/data-project-equipment="哑铃"/);assert.match(html,/不限器械/);const arms=a.run("projectResults('free','','哑铃','arms')");assert.match(arms,/哑铃弯举/);assert.doesNotMatch(arms,/绳索下压/);assert.match(arms,/project-suggested-card/);assert.match(arms,/<animate /);const body=a.run("projectResults('free','','徒手','arms')");assert.match(body,/俯卧撑/);assert.match(body,/project-suggested-card/);assert.equal(a.run('records.length'),0);assert.equal(a.run('draft'),null)});

test('bodyweight arm choices include push-up variants while preserving their primary muscle and zero load volume',()=>{const a=app();const list=Array.from(a.run("matchingProjects('free','','徒手','arms').map(e=>e.name)"));for(const name of ['俯卧撑','墙壁俯卧撑','跪姿俯卧撑','窄距俯卧撑','上斜俯卧撑','跪姿窄距俯卧撑'])assert.ok(list.includes(name),name);assert.equal(a.run("exerciseInfo({name:'俯卧撑'}).muscle"),'胸部');assert.equal(a.run("startFreeWorkout({exercise:'跪姿俯卧撑',sets:'1',reps:'10'})"),true);a.run('completeSet(0);finishWorkout()');assert.equal(a.run('records[0].volume'),0);assert.equal(a.run('records[0].items[0].sets[0].weight'),null);assert.equal(a.run('exerciseCatalog.length'),60)});

test('expanded muscle search includes compound actions and existing custom names retain their metadata',()=>{const a=app();assert.ok(a.run("matchingProjects('free','手部','徒手').some(e=>e.name==='俯卧撑')"));a.run("profile.customExercises=[{name:'徒手深蹲',muscle:'下肢',equipment:'自定义',type:'weighted',reference:3,custom:true}]");assert.equal(a.run("allExercises().filter(e=>e.name==='徒手深蹲').length"),1);assert.equal(a.run("exerciseInfo({name:'徒手深蹲'}).type"),'weighted')});

test('selected motion survives renamed free action and remains visible during set rest and pause',()=>{const a=app();a.run("startFreeWorkout({exercise:'我的俯卧撑',motionKey:'俯卧撑',type:'bodyweight',sets:'2',reps:'10'})");assert.equal(a.run('draft.items[0].motionKey'),'俯卧撑');assert.match(a.element('workout-content').innerHTML,/俯卧撑循环动作示意/);a.run('completeSet(0)');assert.match(a.element('workout-content').innerHTML,/rest-step/);assert.match(a.element('workout-content').innerHTML,/俯卧撑循环动作示意/);a.run('toggleWorkoutPause()');assert.match(a.element('workout-content').innerHTML,/俯卧撑循环动作示意/);});
